const invoiceOld=o=>{if(!o)return;const rows=o.items.map(x=>{const p=x.p??unit(x.i,x.w);return`<tr><td>${PR[x.i][0]} (${wl(x.w)})</td><td>${x.q}</td><td>${inr(p)}</td><td>${inr(p*x.q)}</td></tr>`}).join("");$("#md").className="on wide";$("#md").innerHTML=`<div id="inv"><h2 style="font-size:1.5rem">Invoice (sample)</h2><p class="mu">HKS Holding Pvt. Ltd. · GSTIN and address to be added<br>Invoice INV-${E(o.id.slice(4))} · ${new Date(o.date).toLocaleDateString("en-IN")} · Order ${E(o.id)}</p><p>Bill to: ${o.cust?E(o.cust.name)+", "+E(o.cust.email):"Customer"}<br>${atxt(o.addr)}</p><table class="tb2"><tr><th>Item</th><th>Qty</th><th>Price</th><th>Amount</th></tr>${rows}</table><div class="sum" style="margin-top:12px">${o.sub!=null?`<div><span>Subtotal</span><span>${inr(o.sub)}</span></div><div><span>Discount</span><span>−${inr(o.disc||0)}</span></div><div><span>Delivery</span><span>${o.ship?inr(o.ship):"Free"}</span></div>`:""}<div class="t"><span>Total</span><span>${inr(o.total)}</span></div></div><p class="mu">Sample invoice generated in the browser. The live system generates GST-compliant invoices.</p><div style="display:flex;gap:8px"><button class="btn bb" data-a="print">Print / Save as PDF</button><button class="btn bo" data-a="close">Close</button></div></div>`;$("#ov").classList.add("on")};
const reveal=()=>{if(!("IntersectionObserver" in window))return;const io=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add("in");io.unobserve(x.target)}}),{threshold:.06});$$("#app .sec,#app .c3s").forEach(el=>{el.classList.add("rvl");io.observe(el)})};
const FAQ=[["How do I choose a weight?","Each product page lists the available pack sizes with the exact price for each."],["How can I track my order?","Open Orders &amp; tracking and enter your order number, or view the progress bar on each order."],["Which payment options will be available?","Online payment through Razorpay (UPI, cards, net banking) and cash on delivery. Online payment is switched on once the business connects its Razorpay account."],["Do you deliver to my PIN code?","Enter your PIN code at checkout to check availability and the estimated delivery window."],["What is the return and refund policy?","The policy will be published here after it is approved by the business."]];
