cart:()=>{const ks=Object.keys(cart);if(!ks.length)return'<div class="card em"><h2>Your cart is empty</h2><p>Add some spices to get started.</p><button class="btn ba" data-a="nav" data-v="all">Continue shopping</button></div>';return`<div class="sm"><div class="card"><h2>Shopping cart</h2>${ks.map(k=>{const[i,w]=k.split("|").map(Number);return`<div class="it"><i style="background:${pic(PR[i][3])}"></i><div><a class="pt" href="#p-${i}">${PR[i][0]}</a><div class="mu">${w} g · ${inr(unit(i,w))} each</div><div class="qt"><button data-a="q" data-v="${k}|-1" aria-label="Decrease">−</button><b>${cart[k]}</b><button data-a="q" data-v="${k}|1" aria-label="Increase">+</button><button class="lnk" data-a="rm" data-v="${k}">Remove</button></div></div><b>${inr(unit(i,w)*cart[k])}</b></div>`}).join("")}</div>${summary(true)}</div>`},
